raw_output:
import numpy as np

if rng is None:
    rng = np.random.default_rng()
if n == 0:
    return np.empty((0, d), dtype=float)

result = np.empty((0, d), dtype=float)
needed = n
while needed > 0:
    # generate a batch, oversample to reduce loops
    batch = max(needed * 2, 1024)
    pts = rng.uniform(-1, 1, size=(batch, d))
    mask = np.linalg.norm(pts, axis=1) <= 1
    accepted = pts[mask]
    if accepted.shape[0] > 0:
        if accepted.shape[0] >= needed:
            result = np.vstack([result, accepted[:needed]])
            needed = 0
        else:
            result = np.vstack([result, accepted])
            needed -= accepted.shape[0]
return result[:n]

