def load(self):
        """Load our config, log and raise on error."""
        try:
            path = getattr(self, "config_path")
            with open(path, "r", encoding="utf-8") as f:
                if str(path).lower().endswith((".yaml", ".yml")):
                    import yaml
                    self.config = yaml.safe_load(f)
                else:
                    import json
                    self.config = json.load(f)
            self.logger.info("Config loaded from %s", path)
        except Exception as exc:
            self.logger.error("Failed to load config from %s: %s", getattr(self, "config_path", "<unknown>"), exc)
            raise

