mgc_code:
def set_mypy_path(mypy_path):
    """Prepend to MYPYPATH."""
    import os
    if not mypy_path:
        return os.getenv("MYPYPATH", "")
    existing = os.getenv("MYPYPATH")
    if existing:
        new_path = mypy_path + os.pathsep + existing
    else:
        new_path = mypy_path
    os.environ["MYPYPATH"] = new_path
    return new_path

